def largestPowerArray(nums: list[int], limit: int) -> list[int]:
    n = len(nums)
    sorted_pairs = sorted([(nums[i], i) for i in range(n)])

    groups = []
    curr_group = [sorted_pairs[0]]
    for i in range(1, n):
        if sorted_pairs[i][0] - sorted_pairs[i - 1][0] <= limit:
            curr_group.append(sorted_pairs[i])
        else:
            groups.append(curr_group)
            curr_group = [sorted_pairs[i]]
    groups.append(curr_group)

    res = [0] * n
    for group in groups:
        indices = sorted([idx for val, idx in group])
        values = sorted([val for val, idx in group], reverse=True)
        for idx, val in zip(indices, values):
            res[idx] = val

    return res

#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> largestPowerArray(std::vector<int>& nums, int limit) {
        int n = nums.size();
        std::vector<std::pair<int, int>> pairs;
        for (int i = 0; i < n; ++i) pairs.push_back({nums[i], i});
        std::sort(pairs.begin(), pairs.end());

        std::vector<int> res(n);
        int i = 0;
        while (i < n) {
            int j = i;
            std::vector<int> idxs = {pairs[i].second};
            std::vector<int> vals = {pairs[i].first};
            while (j + 1 < n && pairs[j + 1].first - pairs[j].first <= limit) {
                j++;
                idxs.push_back(pairs[j].second);
                vals.push_back(pairs[j].first);
            }
            std::sort(idxs.begin(), idxs.end());
            std::sort(vals.begin(), vals.end(), std::greater<int>());
            for (size_t k = 0; k < idxs.size(); ++k) {
                res[idxs[k]] = vals[k];
            }
            i = j + 1;
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] largestPowerArray(int[] nums, int limit) {
        int n = nums.length;
        int[][] pairs = new int[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums[i];
            pairs[i][1] = i;
        }
        Arrays.sort(pairs, (a, b) -> Integer.compare(a[0], b[0]));

        int[] res = new int[n];
        int i = 0;
        while (i < n) {
            int j = i;
            List<Integer> idxs = new ArrayList<>();
            List<Integer> vals = new ArrayList<>();
            idxs.add(pairs[i][1]);
            vals.add(pairs[i][0]);
            while (j + 1 < n && pairs[j + 1][0] - pairs[j][0] <= limit) {
                j++;
                idxs.add(pairs[j][1]);
                vals.add(pairs[j][0]);
            }
            Collections.sort(idxs);
            vals.sort(Collections.reverseOrder());
            for (int k = 0; k < idxs.size(); k++) {
                res[idxs.get(k)] = vals.get(k);
            }
            i = j + 1;
        }
        return res;
    }
}

